Lemma map_contains_intro : forall l (lo n : word) e, In e l ->
  bv_unsigned (fst e) <= bv_unsigned lo -> bv_unsigned lo + bv_unsigned n <= bv_unsigned (fst e) + bv_unsigned (snd e) ->
